namespace Jeninnet.Localization.Analyzers.Localizability.CodeFixes;

/// <summary>
/// Code fix for JLNLOC001: when the flagged literal equals a
/// <c>const string</c> in a <c>*Keys</c> class (hand-written like
/// <c>ReferenceKeys</c> or generated by), offer to reference that constant.
/// Fully namespace-qualified replacement, so no usings change: mechanical and
/// behavior-preserving (same string value, compile-time name). Literals with no
/// matching constant get no fix — the diagnostic stays until the author moves the
/// text to a catalog.
/// Lives in its own assembly because fixes require Microsoft.CodeAnalysis.Workspaces,
/// which RS1038 forbids in analyzer assemblies; the DLL travels inside the analyzer
/// package. The diagnostic ID mirrors the analyzer's descriptor.
/// </summary>
[ExportCodeFixProvider(LanguageNames.CSharp, Name = nameof(LocalizabilityCodeFixProvider))]
public sealed class LocalizabilityCodeFixProvider : CodeFixProvider {
    /// <summary>
    /// The fixed diagnostic ID (mirrors the analyzer descriptor).
    /// </summary>
    internal const string DIAGNOSTIC_ID = "JLNLOC001";

    /// <inheritdoc/>
    public override ImmutableArray<string> FixableDiagnosticIds =>
        [DIAGNOSTIC_ID];

    /// <inheritdoc/>
    public override FixAllProvider? GetFixAllProvider() => null;

    /// <inheritdoc/>
    public override async Task RegisterCodeFixesAsync(CodeFixContext context) {
        var diagnostic = context.Diagnostics.FirstOrDefault(static candidate =>
            candidate.Id.Equals(DIAGNOSTIC_ID, StringComparison.Ordinal));
        if(diagnostic?.Location.SourceTree is null) {
            return;
        }

        var document = context.Document;
        var root = await document.GetSyntaxRootAsync(context.CancellationToken).ConfigureAwait(false);
        var literal = root?.FindNode(diagnostic.Location.SourceSpan).FirstAncestorOrSelf<LiteralExpressionSyntax>();
        if(literal is null || literal.Token.ValueText.Length == 0) {
            return;
        }

        var model = await document.GetSemanticModelAsync(context.CancellationToken).ConfigureAwait(false);
        if(model?.Compilation is null) {
            return;
        }

        var match = FindConstant(model.Compilation, literal.Token.ValueText);
        if(match is null) {
            return;
        }

        context.RegisterCodeFix(
            CodeAction.Create(
                title: $"Use {match.TypeName}.{match.FieldName}",
                createChangedDocument: cancellationToken => ApplyFixAsync(document, literal, match.QualifiedName, cancellationToken),
                equivalenceKey: "JLNLOC001_Use_" + match.QualifiedName),
            diagnostic);
    }

    /// <summary>
    /// Finds constant.
    /// </summary>
    /// <param name="compilation">The compilation.</param>
    /// <param name="value">The value.</param>
    /// <returns>The constant result.</returns>
    internal static ConstantMatch? FindConstant(Compilation compilation, string value) {
        if(compilation is null) {
            throw new ArgumentNullException(nameof(compilation));
        }

        if(value is null) {
            throw new ArgumentNullException(nameof(value));
        }

        ConstantMatch? best = null;
        foreach(var type in AllSourceTypes(compilation.GlobalNamespace)) {
            if(!type.Name.EndsWith("Keys", StringComparison.Ordinal)) {
                continue;
            }

            foreach(var member in type.GetMembers()) {
                if(member is not IFieldSymbol field ||
                   !field.IsConst ||
                   field.Type?.SpecialType != SpecialType.System_String ||
                   !field.HasConstantValue ||
                   (field.ConstantValue as string) != value) {
                    continue;
                }

                var qualified = type.ToDisplayString() + "." + field.Name;
                var candidate = new ConstantMatch(type.Name, field.Name, qualified);
                if(best is null || string.CompareOrdinal(candidate.QualifiedName, best.QualifiedName) < 0) {
                    best = candidate;
                }
            }
        }

        return best;
    }

    /// <summary>
    /// Applies fix.
    /// </summary>
    /// <param name="document">The document.</param>
    /// <param name="literal">The literal.</param>
    /// <param name="qualifiedName">The qualified name.</param>
    /// <param name="cancellationToken">A token to cancel the operation.</param>
    /// <returns>A task whose result is fix.</returns>
    private static async Task<Document> ApplyFixAsync(Document document, LiteralExpressionSyntax literal, string qualifiedName, CancellationToken cancellationToken) {
        var root = await document.GetSyntaxRootAsync(cancellationToken).ConfigureAwait(false);
        if(root is null) {
            return document;
        }

        var replacement = Microsoft.CodeAnalysis.CSharp.SyntaxFactory.ParseExpression(qualifiedName)
            .WithTriviaFrom(literal);
        return document.WithSyntaxRoot(root.ReplaceNode(literal, replacement));
    }

    /// <summary>
    /// Performs the all source types operation.
    /// </summary>
    /// <param name="space">The space.</param>
    /// <returns>The all source types sequence.</returns>
    private static IEnumerable<INamedTypeSymbol> AllSourceTypes(INamespaceSymbol space) {
        foreach(var member in space.GetMembers()) {
            if(member is INamespaceSymbol nested) {
                foreach(var type in AllSourceTypes(nested)) {
                    yield return type;
                }
            } else if(member is INamedTypeSymbol type &&
                      type.Locations.Any(static location => location.IsInSource)) {
                yield return type;

                foreach(var nestedType in AllNestedTypes(type)) {
                    yield return nestedType;
                }
            }
        }
    }

    /// <summary>
    /// Performs the all nested types operation.
    /// </summary>
    /// <param name="type">The type.</param>
    /// <returns>The all nested types sequence.</returns>
    private static IEnumerable<INamedTypeSymbol> AllNestedTypes(INamedTypeSymbol type) {
        foreach(var member in type.GetMembers()) {
            if(member is INamedTypeSymbol nested && nested.Locations.Any(static location => location.IsInSource)) {
                yield return nested;

                foreach(var deeper in AllNestedTypes(nested)) {
                    yield return deeper;
                }
            }
        }
    }

    /// <summary>
    /// Represents a constant match.
    /// </summary>
    /// <param name="typeName">The type name.</param>
    /// <param name="fieldName">The field name.</param>
    /// <param name="qualifiedName">The qualified name.</param>
    internal sealed class ConstantMatch(string typeName, string fieldName, string qualifiedName) {
        /// <summary>
        /// Gets the type name.
        /// </summary>
        public string TypeName { get; } = typeName;

        /// <summary>
        /// Gets the field name.
        /// </summary>
        public string FieldName { get; } = fieldName;

        /// <summary>
        /// Gets the qualified name.
        /// </summary>
        public string QualifiedName { get; } = qualifiedName;
    }
}
